/**
 * くわらぼの画像アセット。
 *
 * 単一HTML (Artifact) として配布するため public/ に置かず data URI で同梱している。
 * 元画像はフラットデザインで生成したもの。書き出し時に本体が半透明になり
 * 周囲に暗いグローが焼き込まれていたため、アルファ200をしきい値に抜き出して
 * 本体を完全不透明へ揃えてから WebP (256px, q88) に変換した。
 */

/** アプリアイコン: 生成りの角丸タイル込み */
export const APP_ICON_SRC =
  "data:image/webp;base64,";

/** 種類別のクワガタ (上面図・背景透過) */
const SP = {
  ookuwa:
    "data:image/webp;base64,",
  hirata:
    "data:image/webp;base64,",
  kokuwa:
    "data:image/webp;base64,",
  nokogiri:
    "data:image/webp;base64,",
  miyama:
    "data:image/webp;base64,",
  nijiiro:
    "data:image/webp;base64,",
  tarandus:
    "data:image/webp;base64,",
  ougononi:
    "data:image/webp;base64,",
} as const;

/** 種類名 → 画像。絵のない種は見た目の近い種を流用する */
const SPECIES_IMAGE: Record<string, string> = {
  "オオクワガタ": SP.ookuwa,
  "ヒラタクワガタ": SP.hirata,
  "コクワガタ": SP.kokuwa,
  "ノコギリクワガタ": SP.nokogiri,
  "ミヤマクワガタ": SP.miyama,
  "ニジイロクワガタ": SP.nijiiro,
  "タランドゥスオオツヤクワガタ": SP.tarandus,
  "オウゴンオニクワガタ": SP.ougononi,
  "パラワンオオヒラタ": SP.hirata,
  "スマトラオオヒラタ": SP.hirata,
  "アンタエウスオオクワガタ": SP.ookuwa,
  "ギラファノコギリクワガタ": SP.nokogiri,
};

export function speciesImage(species: string): string {
  return SPECIES_IMAGE[species] ?? SP.ookuwa;
}
